from scapy.all import *
import re

def extract_bmp():
    packets = rdpcap('cap.pcap')
    bmp_data = b''

    for packet in packets:
        if Raw in packet and b'POST' in packet[Raw].load:
            # Look for x= parameter with hex values
            content = packet[Raw].load.decode('latin-1')
            x_match = re.search(r'&x=([^&\n"]*)', content)
            if x_match:
                hex_str = x_match.group(1)
                try:
                    # Convert hex values to bytes
                    bmp_part = bytes.fromhex(hex_str.replace('ff', ''))
                    bmp_data += bmp_part
                except:
                    continue

    # Write BMP file
    if bmp_data:
        with open('output.bmp', 'wb') as f:
            f.write(b'BM' + bmp_data)  # Add BMP header

if __name__ == '__main__':
    extract_bmp()

