from scapy.all import *
import binascii

def extract_bmp():
    packets = rdpcap('cap.pcap')
    hex_data = b''

    # Look for HTTP POST data containing x parameter
    for packet in packets:
        if Raw in packet and b'POST' in packet[Raw].load:
            data = packet[Raw].load
            if b'x=' in data:
                # Extract the x parameter value
                start = data.find(b'x=') + 2
                end = data.find(b'&', start) if b'&' in data[start:] else len(data)
                hex_part = data[start:end]
                if hex_part and all(c in b'0123456789abcdefABCDEF' for c in hex_part):
                    # Convert hex string to bytes
                    try:
                        hex_data += binascii.unhexlify(hex_part)
                    except:
                        continue

    # Write BMP file if we found data
    if hex_data.startswith(b'BM'):
        with open('output_final.bmp', 'wb') as f:
            f.write(hex_data)
        print("BMP file extracted successfully!")
    else:
        print("No valid BMP data found.")

extract_bmp()
